INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('SCIE.G5.LIVING.CLASSIFICATION_OF_PLANTS.FLOWERING_OR_NOT', 'SCIE.G4.LIVING.PLANTS.PLANT_LIFE_CHARS', 'skill', 'essential', 'Grade 4 showed that plants reproduce; flowers and cones are how they do it. Proposed, to confirm by a CBC Science and Technology teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('SCIE.G5.LIVING.CLASSIFICATION_OF_PLANTS.FLOWER_PART_NAMES', 'SCIE.G4.LIVING.PLANTS.b', 'outcome', 'essential', 'External parts of a plant; the flower is one of them.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('SCIE.G5.LIVING.CLASSIFICATION_OF_PLANTS.FLOWER_PART_NAMES', 'SCIE.G4.LIVING.PLANTS.PLANT_PART_FUNCTIONS', 'skill', 'essential', 'The child names the root, stem and leaf before the parts of a flower. Proposed, to confirm by a CBC Science and Technology teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('SCIE.G5.LIVING.CLASSIFICATION_OF_PLANTS.FLOWER_PART_FUNCTIONS', 'SCIE.G5.LIVING.CLASSIFICATION_OF_PLANTS.FLOWER_PART_NAMES', 'skill', 'essential', 'The child must know the part before learning its job.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('SCIE.G5.LIVING.CLASSIFICATION_OF_PLANTS.FLOWER_PART_FUNCTIONS', 'SCIE.G4.LIVING.PLANTS.PLANT_LIFE_CHARS', 'skill', 'essential', 'The jobs of the flower parts are about reproduction, a sign of life met in Grade 4. Proposed, to confirm by a CBC Science and Technology teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('SCIE.G5.LIVING.CLASSIFICATION_OF_PLANTS.FLOWER_TO_SEED', 'SCIE.G5.LIVING.CLASSIFICATION_OF_PLANTS.FLOWER_PART_FUNCTIONS', 'skill', 'essential', 'Pollen, stigma and ovary jobs are needed to follow the steps.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('SCIE.G5.LIVING.CLASSIFICATION_OF_PLANTS.FLOWER_TO_SEED', 'SCIE.G5.LIVING.CLASSIFICATION_OF_PLANTS.FLOWER_PART_NAMES', 'skill', 'essential', 'The child follows pollen from the anther to the stigma and the ovary, so the names come first. Proposed, to confirm by a CBC Science and Technology teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('SCIE.G5.LIVING.CLASSIFICATION_OF_PLANTS.IMPORTANCE_OF_FLOWERS', 'SCIE.G5.LIVING.CLASSIFICATION_OF_PLANTS.FLOWER_TO_SEED', 'skill', 'helpful', 'Fruits and seeds from flowers are the central importance.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('SCIE.G5.LIVING.CLASSIFICATION_OF_PLANTS.IMPORTANCE_OF_FLOWERS', 'SCIE.G5.LIVING.CLASSIFICATION_OF_PLANTS.FLOWERING_OR_NOT', 'skill', 'essential', 'The child must know which plants flower to link flowers with foods such as maize and beans. Proposed, to confirm by a CBC Science and Technology teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('SCIE.G5.LIVING.VERTEBRATES.VERTEBRATE_CHARACTERISTICS', 'SCIE.G4.LIVING.ANIMALS.b', 'outcome', 'essential', 'Grade 4 distinguished vertebrates from invertebrates.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('SCIE.G5.LIVING.VERTEBRATES.VERTEBRATE_CHARACTERISTICS', 'SCIE.G4.LIVING.ANIMALS.a', 'outcome', 'helpful', 'Characteristics of animals as living things.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('SCIE.G5.LIVING.VERTEBRATES.VERTEBRATE_CHARACTERISTICS', 'SCIE.G4.LIVING.ANIMALS.VERTEBRATE_RULE', 'skill', 'essential', 'Grade 4 gave the backbone as the rule for vertebrates; Grade 5 builds the other shared features on it. Proposed, to confirm by a CBC Science and Technology teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('SCIE.G5.LIVING.VERTEBRATES.VERTEBRATE_GROUPS', 'SCIE.G5.LIVING.VERTEBRATES.VERTEBRATE_CHARACTERISTICS', 'skill', 'essential', 'The child must first know the animal is a vertebrate.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('SCIE.G5.LIVING.VERTEBRATES.VERTEBRATE_GROUPS', 'SCIE.G4.LIVING.ANIMALS.VERTEBRATE_SORT', 'skill', 'essential', 'The child must first pick out the vertebrates before putting them into five groups. Proposed, to confirm by a CBC Science and Technology teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('SCIE.G5.LIVING.VERTEBRATES.VERTEBRATE_FEATURES', 'SCIE.G5.LIVING.VERTEBRATES.VERTEBRATE_GROUPS', 'skill', 'helpful', 'Naming the groups and their features support each other.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('SCIE.G5.LIVING.VERTEBRATES.VERTEBRATE_FEATURES', 'SCIE.G5.LIVING.VERTEBRATES.VERTEBRATE_CHARACTERISTICS', 'skill', 'essential', 'Features are of vertebrates.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('SCIE.G5.LIVING.THE_HUMAN_BREATHING_SYST.BREATHING_PARTS', 'SCIE.G4.LIVING.HUMAN_DIGESTIVE_SYSTEM.a', 'outcome', 'helpful', 'Knowing the digestive parts helps the child keep the two pipes apart.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('SCIE.G5.LIVING.THE_HUMAN_BREATHING_SYST.BREATHING_PARTS', 'SCIE.G4.LIVING.HUMAN_DIGESTIVE_SYSTEM.DIGESTIVE_PARTS', 'skill', 'essential', 'Knowing the food pipe from Grade 4 keeps the windpipe apart from it. Proposed, to confirm by a CBC Science and Technology teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('SCIE.G5.LIVING.THE_HUMAN_BREATHING_SYST.BREATHING_FUNCTIONS', 'SCIE.G5.LIVING.THE_HUMAN_BREATHING_SYST.BREATHING_PARTS', 'skill', 'essential', 'The child names the parts before giving their jobs.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('SCIE.G5.LIVING.THE_HUMAN_BREATHING_SYST.BREATHING_FUNCTIONS', 'SCIE.G4.MATTER.PROPERTIES_OF_MATTER.STATE_PROPERTIES', 'skill', 'essential', 'Air is a gas that takes up space and moves; the child needs this to follow air into the lungs. Proposed, to confirm by a CBC Science and Technology teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
