INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('SCIE.G5.FORCE_.HEAT_TRANSFER.HEAT_CONDUCTORS', 'SCIE.G4.FORCE_.HEAT.HEAT_SAFETY', 'skill', 'essential', 'Holding a hot pot with the right cloth is where conductors and insulators matter first. Proposed, to confirm by a CBC Science and Technology teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
