INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('SCIE.G5.FORCE_.HEAT_TRANSFER.HEAT_USES', 'SCIE.G5.FORCE_.HEAT_TRANSFER.HEAT_CONDUCTORS', 'skill', 'essential', 'Uses of conductors and insulators.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('SCIE.G5.FORCE_.HEAT_TRANSFER.HEAT_USES', 'SCIE.G4.FORCE_.HEAT.HEAT_USES', 'skill', 'essential', 'Uses of heat from Grade 4 are explained here by how the heat is moved. Proposed, to confirm by a CBC Science and Technology teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('SCIE.G5.FORCE_.HEAT_TRANSFER.HEAT_SAFETY', 'SCIE.G4.FORCE_.HEAT.c', 'outcome', 'essential', 'Grade 4 outcome on safety measures when using heat.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
