INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('SCIE.G5.FORCE_.HEAT_TRANSFER.HEAT_SAFETY', 'SCIE.G4.FORCE_.HEAT.HEAT_SAFETY', 'skill', 'essential', 'Grade 4 safety rules are given reasons here: metal handles conduct heat. Proposed, to confirm by a CBC Science and Technology teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.LIVING.CLASSIFICATION_OF_PLANTS.FLOWERING_OR_NOT.M_FL_SMALL_FLOWER_NOT_FLOWER', 'SCIE.G5.LIVING.CLASSIFICATION_OF_PLANTS.FLOWERING_OR_NOT', 'Thinks a plant with no big, bright flowers (maize, grass, kale, mango) does not flower.', '{"question":"Is a maize plant a flowering plant or a non-flowering plant?","wrong_answer":"Non-flowering plant","correct_answer":"Flowering plant"}'::jsonb, 'The child counts only showy petals as flowers. The flowers of maize (the tassel and the silk), grasses and many trees are small and green or yellow.', 'Use crops and grasses, never roses or hibiscus, and offer the answer "non-flowering".', 'Look closely at a maize tassel and a young cob with the class and call both flowers. Anything that makes seeds inside a fruit or grain belongs to the flowering plants.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.LIVING.CLASSIFICATION_OF_PLANTS.FLOWERING_OR_NOT.M_FL_ALL_TREES_FLOWER', 'SCIE.G5.LIVING.CLASSIFICATION_OF_PLANTS.FLOWERING_OR_NOT', 'Thinks every tree is a flowering plant, including cypress and pine, which make cones.', '{"question":"Is a cypress tree a flowering or a non-flowering plant?","wrong_answer":"Flowering plant","correct_answer":"Non-flowering plant"}'::jsonb, 'The child sorts by size or by being a plant with seeds, and has not met cones as a different way of making seeds.', 'Offer cypress or pine next to mango and ask for flowering or non-flowering.', 'Show a cypress cone. Cones hold seeds but they are not flowers and there is no fruit. Compare with a mango flower and fruit.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.LIVING.CLASSIFICATION_OF_PLANTS.FLOWERING_OR_NOT.M_FL_ALL_PLANTS_FLOWER', 'SCIE.G5.LIVING.CLASSIFICATION_OF_PLANTS.FLOWERING_OR_NOT', 'Thinks every plant has flowers, so ferns and mosses must flower too.', '{"question":"Does a fern make flowers?","wrong_answer":"Yes, but very small ones","correct_answer":"No"}'::jsonb, 'The child assumes all green plants flower, because the plants at home and at school all do.', 'Ask about ferns or mosses and offer "yes, hidden flowers".', 'Look at the underside of a fern frond for the spore cases, and at moss capsules. These plants never make flowers.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.LIVING.CLASSIFICATION_OF_PLANTS.FLOWERING_OR_NOT.M_FL_NOT_FLOWERING_NOW', 'SCIE.G5.LIVING.CLASSIFICATION_OF_PLANTS.FLOWERING_OR_NOT', 'Decides by what the plant looks like today: a bean or kale plant with no flower this week is "non-flowering".', '{"question":"A kale plant in a shamba has no flowers this week. Is kale a non-flowering plant?","wrong_answer":"Yes, because it has no flowers now","correct_answer":"No, kale makes flowers when it is left to grow"}'::jsonb, 'The child classifies by the moment of looking, not by what the plant can do over its whole life.', 'Describe a flowering plant that has not flowered yet, such as a bean seedling or kale cut every week.', 'Follow one bean plant through weeks: seedling, flower, pod. A plant is flowering if it makes flowers at some time in its life.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.LIVING.CLASSIFICATION_OF_PLANTS.FLOWER_PART_NAMES.M_PN_PETAL_SEPAL', 'SCIE.G5.LIVING.CLASSIFICATION_OF_PLANTS.FLOWER_PART_NAMES', 'Mixes up petals and sepals, calling the small green parts below the flower the petals.', '{"question":"Which part is the small green leaf-like part at the base of a flower?","wrong_answer":"Petal","correct_answer":"Sepal"}'::jsonb, 'The child names the part by the word they know best (petal) and has not looked at the green ring under the coloured petals.', 'Describe the green part by position and colour and offer petal as a distractor.', 'Take a bean or hibiscus flower apart. Petals are coloured and on the inside. Sepals are green and underneath, and they covered the bud.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.LIVING.CLASSIFICATION_OF_PLANTS.FLOWER_PART_NAMES.M_PN_STAMEN_PISTIL', 'SCIE.G5.LIVING.CLASSIFICATION_OF_PLANTS.FLOWER_PART_NAMES', 'Swaps the stamen and the pistil.', '{"question":"Which part of a flower is the stamen?","wrong_answer":"The part in the middle with the ovary at its base","correct_answer":"The part with a thin stalk and a small pollen-holding top"}'::jsonb, 'The words sound alike and both stand in the middle of the flower.', 'Ask for the part with pollen, and offer the pistil.', 'Say the rhyme: STamen has the pollen (Sticks up with an anther), PIStil has the Pip (seed) place. Draw both from a real flower.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.LIVING.CLASSIFICATION_OF_PLANTS.FLOWER_PART_NAMES.M_PN_STIGMA_ANTHER', 'SCIE.G5.LIVING.CLASSIFICATION_OF_PLANTS.FLOWER_PART_NAMES', 'Thinks the stigma is the top of the stamen, or that the anther is part of the pistil.', '{"question":"Which part of a flower is sticky and catches pollen?","wrong_answer":"Anther","correct_answer":"Stigma"}'::jsonb, 'The child knows both are small knobs at the top of a thin part and mixes them up.', 'Ask which part holds pollen and which part catches pollen, with both names as options.', 'Pollen is made on the anther (A for "at the stamen") and lands on the sticky stigma (S for "sticky").', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.LIVING.CLASSIFICATION_OF_PLANTS.FLOWER_PART_FUNCTIONS.M_PF_PETAL_SEPAL_JOBS', 'SCIE.G5.LIVING.CLASSIFICATION_OF_PLANTS.FLOWER_PART_FUNCTIONS', 'Gives the sepals the job of attracting insects and the petals the job of protecting the bud.', '{"question":"Which part of a flower protects the bud before it opens?","wrong_answer":"Petals","correct_answer":"Sepals"}'::jsonb, 'The child has swapped the two names or has assumed the bigger, brighter part does the protecting.', 'Ask for the protecting part and offer petals first.', 'Show a bud: the green sepals wrap it. Then show an open flower: the bright petals are the sign for insects.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.LIVING.CLASSIFICATION_OF_PLANTS.FLOWER_PART_FUNCTIONS.M_PF_POLLEN_IS_SEED', 'SCIE.G5.LIVING.CLASSIFICATION_OF_PLANTS.FLOWER_PART_FUNCTIONS', 'Thinks pollen is a seed, or that the stamen makes the seeds.', '{"question":"Which part of a flower makes pollen?","wrong_answer":"Ovary","correct_answer":"Anther"}'::jsonb, 'The child links a flower with seeds and has not separated pollen (made on the anther) from seeds (made in the ovary after pollen arrives).', 'Ask what the stamen makes and offer "seeds".', 'Rub an anther on paper to see the yellow pollen. Then cut open a young bean pod: the seeds grow in the ovary. They are different things.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.LIVING.CLASSIFICATION_OF_PLANTS.FLOWER_PART_FUNCTIONS.M_PF_OVARY_MAKES_POLLEN', 'SCIE.G5.LIVING.CLASSIFICATION_OF_PLANTS.FLOWER_PART_FUNCTIONS', 'Gives the ovary the job of making pollen, or gives the anther the job of holding the seeds.', '{"question":"Which part of a flower holds the ovules that later become seeds?","wrong_answer":"Anther","correct_answer":"Ovary"}'::jsonb, 'The child knows the flower makes both pollen and seeds but has not tied each to its own part.', 'Offer the anther as the part that holds ovules.', 'Make a two-column chart: anther - makes pollen; ovary - holds ovules, later the seeds.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.LIVING.CLASSIFICATION_OF_PLANTS.FLOWER_TO_SEED.M_FS_FRUIT_NOT_FROM_FLOWER', 'SCIE.G5.LIVING.CLASSIFICATION_OF_PLANTS.FLOWER_TO_SEED', 'Thinks fruits grow straight from the stem or roots, not from the flower.', '{"question":"From which part of a pumpkin plant does the pumpkin fruit grow?","wrong_answer":"The root","correct_answer":"The flower (its ovary)"}'::jsonb, 'The child sees fruit hanging from the plant and has never watched the flower wither and the fruit swell in its place.', 'Ask where a fruit comes from and offer root or stem.', 'Watch a tomato or pumpkin flower for two weeks: the petals drop and the base of the flower swells into the fruit.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.LIVING.CLASSIFICATION_OF_PLANTS.FLOWER_TO_SEED.M_FS_POLLINATION_DISPERSAL', 'SCIE.G5.LIVING.CLASSIFICATION_OF_PLANTS.FLOWER_TO_SEED', 'Mixes up pollination (carrying pollen to a stigma) with carrying seeds away to new places.', '{"question":"A bee moves from one pumpkin flower to another with yellow dust on its legs. What is happening?","wrong_answer":"Seeds are being carried to a new place","correct_answer":"Pollen is being carried to a stigma"}'::jsonb, 'The child knows animals and wind help plants spread and uses one idea for both jobs.', 'Describe pollen movement and offer seed dispersal.', 'Two charts: pollination is before the seed (pollen to stigma). Dispersal is after (seed to new ground).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.LIVING.CLASSIFICATION_OF_PLANTS.FLOWER_TO_SEED.M_FS_BEES_NOT_NEEDED', 'SCIE.G5.LIVING.CLASSIFICATION_OF_PLANTS.FLOWER_TO_SEED', 'Thinks flowers make fruits whether or not pollen ever reaches them, so bees and the wind do not matter.', '{"question":"A farmer sprays a pesticide that kills all the bees near his pumpkin flowers. What is likely to happen to the pumpkins?","wrong_answer":"They will still grow just as many fruits","correct_answer":"Fewer fruits will grow"}'::jsonb, 'The child thinks the plant fills the fruit on its own and does not link pollen arriving with seeds starting to grow.', 'Give a scenario with no pollinators and offer "no change".', 'Compare a flower covered with a net bag (no visitors) and an open one over two weeks.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.LIVING.CLASSIFICATION_OF_PLANTS.IMPORTANCE_OF_FLOWERS.M_IM_ONLY_DECORATION', 'SCIE.G5.LIVING.CLASSIFICATION_OF_PLANTS.IMPORTANCE_OF_FLOWERS', 'Thinks flowers are only for decoration and smell.', '{"question":"Why are flowers important in nature, apart from looking beautiful?","wrong_answer":"They are only there to look and smell nice","correct_answer":"They make fruits and seeds and feed bees and other insects"}'::jsonb, 'The child knows flowers from bouquets and gardens and has not thought about what they do for the plant.', 'Ask for the importance of flowers and offer "to look nice" as an answer.', 'List everything on the lunch plate that began as a flower: maize, beans, mango, tomato.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.LIVING.CLASSIFICATION_OF_PLANTS.IMPORTANCE_OF_FLOWERS.M_IM_INSECTS_HARM', 'SCIE.G5.LIVING.CLASSIFICATION_OF_PLANTS.IMPORTANCE_OF_FLOWERS', 'Thinks insects on flowers harm the plant and should be killed.', '{"question":"Bees visit the flowers on Wanjiru''s bean plants. What should she think about the bees?","wrong_answer":"They help the plant make seeds, so she should leave them","correct_answer":"They are harming the plant, so she should kill them"}'::jsonb, 'The child knows some insects eat crops and lumps all insects together.', 'Offer "kill the insects" as a distractor.', 'Show a bee carrying pollen. Separate insects that eat leaves from those that carry pollen.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.LIVING.CLASSIFICATION_OF_PLANTS.IMPORTANCE_OF_FLOWERS.M_IM_FOOD_NOT_FROM_FLOWERS', 'SCIE.G5.LIVING.CLASSIFICATION_OF_PLANTS.IMPORTANCE_OF_FLOWERS', 'Does not link everyday foods (mango, beans, tomato, maize grain) with flowers.', '{"question":"Which food came from a flower?","wrong_answer":"Cassava roots","correct_answer":"Mangoes"}'::jsonb, 'The child thinks of flowers as separate from food plants.', 'Ask which food came from a flower and offer a root.', 'Trace a mango back to the mango flower in a season of the year.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.LIVING.CLASSIFICATION_OF_PLANTS.FLOWER_PART_NAMES.M_PN_OVARY_IS_FRUIT', 'SCIE.G5.LIVING.CLASSIFICATION_OF_PLANTS.FLOWER_PART_NAMES', 'Calls the ovary of a fresh flower the "fruit" or the "seed" before it has been pollinated.', '{"question":"In a fresh bean flower, what is the swollen part at the bottom of the pistil called?","wrong_answer":"The fruit","correct_answer":"The ovary"}'::jsonb, 'Has seen the ovary swell into a pod and gives the end result''s name to the start.', 'Offer "The fruit" next to the right answer and ask the question again in a new context.', 'Cut open a fresh flower and a young pod side by side: the ovary becomes the pod later.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.LIVING.CLASSIFICATION_OF_PLANTS.FLOWER_PART_FUNCTIONS.M_PF_NECTAR_FOR_PLANT', 'SCIE.G5.LIVING.CLASSIFICATION_OF_PLANTS.FLOWER_PART_FUNCTIONS', 'Thinks nectar is food for the plant itself, not a reward that draws insects.', '{"question":"What is the job of nectar in a flower?","wrong_answer":"It feeds the plant","correct_answer":"It draws insects, which carry pollen as they feed"}'::jsonb, 'Thinks every part of a plant must feed the plant.', 'Offer "It feeds the plant" next to the right answer and ask the question again in a new context.', 'Watch a bee at a flower: it drinks nectar and leaves with pollen on its body.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.LIVING.CLASSIFICATION_OF_PLANTS.FLOWER_TO_SEED.M_FS_PETALS_BECOME_FRUIT', 'SCIE.G5.LIVING.CLASSIFICATION_OF_PLANTS.FLOWER_TO_SEED', 'Thinks the petals swell and become the fruit.', '{"question":"Which part of a flower grows into the fruit?","wrong_answer":"The petals","correct_answer":"The ovary"}'::jsonb, 'Sees the petals as the "main" part of a flower and expects them to grow on.', 'Offer "The petals" next to the right answer and ask the question again in a new context.', 'Watch a bean or tomato flower for a week: the petals fall off and the ovary swells.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.LIVING.CLASSIFICATION_OF_PLANTS.IMPORTANCE_OF_FLOWERS.M_IM_NO_FLOWER_NO_SEEDS_OK', 'SCIE.G5.LIVING.CLASSIFICATION_OF_PLANTS.IMPORTANCE_OF_FLOWERS', 'Thinks a farmer can get seeds or grain from a crop even if its flowers are all cut off.', '{"question":"A farmer cuts off all the tassels and silk from his maize. Will the cobs fill with grain?","wrong_answer":"Yes, the grain grows anyway","correct_answer":"No: without flowers there is no pollination, so no grain"}'::jsonb, 'Does not link the grain with the flower.', 'Offer "Yes, the grain grows anyway" next to the right answer and ask the question again in a new context.', 'Follow a maize plant: tassel and silk come first, then the grain fills the cob.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.LIVING.VERTEBRATES.VERTEBRATE_CHARACTERISTICS.M_VC_SIZE_DECIDES', 'SCIE.G5.LIVING.VERTEBRATES.VERTEBRATE_CHARACTERISTICS', 'Thinks big animals are vertebrates and small animals are not (or the other way round).', '{"question":"Is a small mouse a vertebrate or an invertebrate?","wrong_answer":"Invertebrate, because it is small","correct_answer":"Vertebrate, because it has a backbone"}'::jsonb, 'The child uses size, which is easy to see, in place of the backbone, which is hidden.', 'Use a very small vertebrate (mouse, gecko) and a big invertebrate (crab, octopus).', 'Feel your own backbone, then compare with the thin skeleton of a small fish.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.LIVING.VERTEBRATES.VERTEBRATE_CHARACTERISTICS.M_VC_NEEDS_LEGS', 'SCIE.G5.LIVING.VERTEBRATES.VERTEBRATE_CHARACTERISTICS', 'Thinks an animal with no legs (snake, fish) cannot be a vertebrate.', '{"question":"A snake has no legs. Is a snake a vertebrate?","wrong_answer":"No, because it has no legs","correct_answer":"Yes, because it has a backbone"}'::jsonb, 'The child links "animal with bones" with legs to stand on.', 'Use a snake or a fish and offer legs as the reason.', 'Look at a snake skeleton picture: a long backbone with many bones.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.LIVING.VERTEBRATES.VERTEBRATE_CHARACTERISTICS.M_VC_SHELL_IS_BACKBONE', 'SCIE.G5.LIVING.VERTEBRATES.VERTEBRATE_CHARACTERISTICS', 'Thinks a hard shell or hard outside (crab, beetle, snail) means the animal has a backbone.', '{"question":"A crab has a hard shell. Is a crab a vertebrate?","wrong_answer":"Yes, because its shell is hard like a bone","correct_answer":"No, because it has no backbone"}'::jsonb, 'The child has seen hard parts on the animal and takes them for bones.', 'Use crab, beetle or snail with "hard shell" as the offered reason.', 'Compare the inside skeleton of a fish with the outside shell of a crab.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.LIVING.VERTEBRATES.VERTEBRATE_GROUPS.M_VG_BAT_BIRD', 'SCIE.G5.LIVING.VERTEBRATES.VERTEBRATE_GROUPS', 'Thinks a bat is a bird because it flies.', '{"question":"To which group does a bat belong?","wrong_answer":"Birds","correct_answer":"Mammals"}'::jsonb, 'The child groups by how the animal moves, not by body covering and how the young are fed.', 'Offer the bat with birds in the options.', 'A bat has fur and feeds its young on milk. No feathers. Birds have feathers and lay eggs.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.LIVING.VERTEBRATES.VERTEBRATE_GROUPS.M_VG_WATER_IS_FISH', 'SCIE.G5.LIVING.VERTEBRATES.VERTEBRATE_GROUPS', 'Thinks any animal that lives in water is a fish (dolphin, crocodile, hippo, frog).', '{"question":"To which group does a dolphin belong?","wrong_answer":"Fish","correct_answer":"Mammals"}'::jsonb, 'The child groups by habitat, not by body features.', 'Offer dolphin or crocodile with fish in the options.', 'Fish have gills and scales. A dolphin breathes air with lungs and feeds its young on milk.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.LIVING.VERTEBRATES.VERTEBRATE_GROUPS.M_VG_REPTILE_AMPHIBIAN', 'SCIE.G5.LIVING.VERTEBRATES.VERTEBRATE_GROUPS', 'Mixes up reptiles and amphibians (thinking chameleons and lizards are amphibians, or frogs are reptiles).', '{"question":"To which group does a chameleon belong?","wrong_answer":"Amphibians","correct_answer":"Reptiles"}'::jsonb, 'The child knows both groups are cold to the touch and lay eggs and has not looked at the skin.', 'Offer chameleon or frog with the other group.', 'Reptiles have dry scales and lay eggs on land. Amphibians have moist skin and start life in water.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.LIVING.VERTEBRATES.VERTEBRATE_GROUPS.M_VG_NOFLY_NOT_BIRD', 'SCIE.G5.LIVING.VERTEBRATES.VERTEBRATE_GROUPS', 'Thinks a bird that cannot fly (an ostrich) is not a bird.', '{"question":"To which group does an ostrich belong?","wrong_answer":"Mammals, because it cannot fly","correct_answer":"Birds"}'::jsonb, 'The child uses flying to define a bird, not feathers and eggs with hard shells.', 'Offer ostrich and "cannot fly".', 'List what an ostrich has: feathers, wings, a beak, hard-shelled eggs.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.LIVING.VERTEBRATES.VERTEBRATE_GROUPS.M_VG_EGGS_ARE_BIRDS', 'SCIE.G5.LIVING.VERTEBRATES.VERTEBRATE_GROUPS', 'Thinks any animal that lays eggs is a bird.', '{"question":"A crocodile lays eggs. Is it a bird?","wrong_answer":"Yes, because birds lay eggs","correct_answer":"No, it is a reptile"}'::jsonb, 'The child has learned that birds lay eggs and does not know that other groups do too.', 'Use crocodile, tortoise or tilapia with the reason "lays eggs".', 'Make a chart of which groups lay eggs: birds, reptiles, fish, amphibians.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.LIVING.VERTEBRATES.VERTEBRATE_FEATURES.M_VF_SCALES_FISH_ONLY', 'SCIE.G5.LIVING.VERTEBRATES.VERTEBRATE_FEATURES', 'Thinks only fish have scales, so snakes and crocodiles do not.', '{"question":"Which group of vertebrates has dry scales and lays eggs on land?","wrong_answer":"Fish","correct_answer":"Reptiles"}'::jsonb, 'The child links scales with fish because fish scales are the ones seen at the market.', 'Ask for the group with dry scales and offer fish.', 'Look at a snake skin or a chameleon and feel the dry scales. Compare with wet fish scales.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.LIVING.VERTEBRATES.VERTEBRATE_FEATURES.M_VF_WINGS_MEAN_BIRD', 'SCIE.G5.LIVING.VERTEBRATES.VERTEBRATE_FEATURES', 'Thinks any animal with wings is a bird.', '{"question":"Which feature do all birds have, and no other group of vertebrates?","wrong_answer":"Wings","correct_answer":"Feathers"}'::jsonb, 'The child uses wings, the most noticeable feature, and forgets that bats and insects have wings too.', 'Ask for the feature found only in birds and offer wings.', 'List flying animals: a bat has wings but fur; a butterfly has wings but no backbone. Only birds have feathers.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.LIVING.VERTEBRATES.VERTEBRATE_FEATURES.M_VF_AMPHIBIAN_WATER_ONLY', 'SCIE.G5.LIVING.VERTEBRATES.VERTEBRATE_FEATURES', 'Thinks amphibians live only in water, or that the word means "lives in water".', '{"question":"What does it mean when we say a frog is an amphibian?","wrong_answer":"It lives only in water","correct_answer":"It spends part of its life in water and part on land"}'::jsonb, 'The child connects frogs with ponds and does not know the young live in water and adults can live on land.', 'Ask the meaning of amphibian and offer "lives only in water".', 'Follow the life of a frog: eggs and tadpole in water, adult hops on land.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.LIVING.VERTEBRATES.VERTEBRATE_CHARACTERISTICS.M_VC_ALL_WARM', 'SCIE.G5.LIVING.VERTEBRATES.VERTEBRATE_CHARACTERISTICS', 'Thinks all vertebrates are warm-blooded like people.', '{"question":"Is a lizard''s body always warm like a person''s?","wrong_answer":"Yes, all vertebrates are warm","correct_answer":"No: a lizard''s body temperature changes with its surroundings"}'::jsonb, 'Generalises from mammals and birds, the vertebrates the child knows best.', 'Offer "Yes, all vertebrates are warm" next to the right answer and ask the question again in a new context.', 'Watch a lizard bask on a rock in the morning: it warms up in the sun before it moves fast.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.LIVING.VERTEBRATES.VERTEBRATE_FEATURES.M_VF_FEATHERS_ON_BATS', 'SCIE.G5.LIVING.VERTEBRATES.VERTEBRATE_FEATURES', 'Thinks a bat has feathers because it has wings.', '{"question":"What covers the body of a bat?","wrong_answer":"Feathers","correct_answer":"Fur (hair); its wings are skin"}'::jsonb, 'Links wings with feathers.', 'Offer "Feathers" next to the right answer and ask the question again in a new context.', 'Look at a picture of a bat close up: the wing is thin skin between long fingers, the body is furry.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.LIVING.VERTEBRATES.VERTEBRATE_FEATURES.M_VF_ALL_MAMMALS_LAND', 'SCIE.G5.LIVING.VERTEBRATES.VERTEBRATE_FEATURES', 'Thinks mammals live only on land, so a whale or dolphin cannot have hair or feed its young on milk.', '{"question":"A dolphin breathes air and feeds its young on milk. Which group is it in?","wrong_answer":"Fish, because it lives in water","correct_answer":"Mammals"}'::jsonb, 'Uses where an animal lives as the feature, not how it feeds its young.', 'Offer "Fish, because it lives in water" next to the right answer and ask the question again in a new context.', 'List what a dolphin does: breathes air with lungs, gives birth, feeds young on milk.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.LIVING.THE_HUMAN_BREATHING_SYST.BREATHING_PARTS.M_BP_TRACHEA_FOOD', 'SCIE.G5.LIVING.THE_HUMAN_BREATHING_SYST.BREATHING_PARTS', 'Thinks air goes down the same pipe as food, or mixes the windpipe with the food pipe.', '{"question":"Which pipe carries air from the nose to the lungs?","wrong_answer":"The food pipe (gullet)","correct_answer":"The windpipe (trachea)"}'::jsonb, 'The child knows there is one pipe down the neck and does not know there are two.', 'Offer the food pipe as a distractor.', 'Feel the ridged windpipe at the front of the neck. The food pipe is behind it and goes to the stomach.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.LIVING.THE_HUMAN_BREATHING_SYST.BREATHING_PARTS.M_BP_DIAPHRAGM_PLACE', 'SCIE.G5.LIVING.THE_HUMAN_BREATHING_SYST.BREATHING_PARTS', 'Does not know where the diaphragm is (puts it in the neck, or thinks it is part of the lungs).', '{"question":"Which part of the breathing system is the sheet of muscle under the lungs?","wrong_answer":"The trachea","correct_answer":"The diaphragm"}'::jsonb, 'The word is new and is not seen or felt from outside.', 'Describe the diaphragm by position and offer the other names.', 'Draw the body with the diaphragm as a dome under the lungs. Feel your belly rise and fall as you breathe.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.LIVING.THE_HUMAN_BREATHING_SYST.BREATHING_PARTS.M_BP_LUNGS_LOCATION', 'SCIE.G5.LIVING.THE_HUMAN_BREATHING_SYST.BREATHING_PARTS', 'Thinks the lungs are low in the belly, or that there is just one.', '{"question":"Where are the lungs?","wrong_answer":"In the belly, next to the stomach","correct_answer":"In the chest, inside the ribs"}'::jsonb, 'Children draw the body from outside and place the lungs low or in the middle (Mintzes 1984 reports young children''s body-organ drawings).', 'Ask for the position of the lungs and offer the belly.', 'Put hands on the upper chest and feel the ribs moving. The lungs are behind them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.LIVING.THE_HUMAN_BREATHING_SYST.BREATHING_FUNCTIONS.M_BF_AIR_TO_STOMACH', 'SCIE.G5.LIVING.THE_HUMAN_BREATHING_SYST.BREATHING_FUNCTIONS', 'Thinks the air we breathe goes to the stomach.', '{"question":"Where does the air go after the windpipe?","wrong_answer":"To the stomach","correct_answer":"To the lungs"}'::jsonb, 'The child has not separated the two pipes and the idea that "air goes down" ends in the belly.', 'Ask where air goes after the trachea and offer the stomach.', 'Breathe in with the hands on the chest, then on the belly: the chest and the diaphragm move, the stomach does not take in the air.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.LIVING.THE_HUMAN_BREATHING_SYST.BREATHING_FUNCTIONS.M_BF_LUNGS_PUSH_SELF', 'SCIE.G5.LIVING.THE_HUMAN_BREATHING_SYST.BREATHING_FUNCTIONS', 'Thinks the lungs have muscles and fill and empty themselves like balloons.', '{"question":"What helps the lungs fill with air when you breathe in?","wrong_answer":"The lungs pull the air in by themselves","correct_answer":"The diaphragm and the muscles between the ribs"}'::jsonb, 'The child treats the lungs as the only moving part, like a balloon that inflates itself.', 'Ask what makes air come in and offer the lungs themselves.', 'Use a bottle with a balloon inside and a balloon sheet at the bottom to model the diaphragm.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.LIVING.THE_HUMAN_BREATHING_SYST.BREATHING_FUNCTIONS.M_BF_NO_OXYGEN_OUT', 'SCIE.G5.LIVING.THE_HUMAN_BREATHING_SYST.BREATHING_FUNCTIONS', 'Thinks we breathe in only oxygen and breathe out only carbon dioxide.', '{"question":"Which statement about the air we breathe out is true?","wrong_answer":"It has no oxygen in it at all","correct_answer":"It still has some oxygen, and more carbon dioxide than the air we breathe in"}'::jsonb, 'The child has heard "oxygen in, carbon dioxide out" and takes it as the whole story.', 'Ask what is in breathed-out air and offer "no oxygen".', 'Remind the class that mouth-to-mouth breathing works because breathed-out air has oxygen left.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.LIVING.THE_HUMAN_BREATHING_SYST.BREATHING_FUNCTIONS.M_BF_NOSE_ONLY_SMELL', 'SCIE.G5.LIVING.THE_HUMAN_BREATHING_SYST.BREATHING_FUNCTIONS', 'Thinks the nose is only for smelling.', '{"question":"Besides smelling, what do the hairs and mucus in the nose do?","wrong_answer":"Nothing, the nose is only for smelling","correct_answer":"They trap dust and germs from the air we breathe in"}'::jsonb, 'The child knows the nose as a sense organ and not as a part of the breathing system.', 'Ask what else the nose does and offer "nothing".', 'Look at a tissue after a dusty day: the dust has been trapped in the nose.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.LIVING.THE_HUMAN_BREATHING_SYST.BREATHING_MOVEMENT.M_BI_RIBS_IN', 'SCIE.G5.LIVING.THE_HUMAN_BREATHING_SYST.BREATHING_MOVEMENT', 'Thinks the chest gets smaller or the ribs move in when we breathe in.', '{"question":"What happens to the chest when you breathe in?","wrong_answer":"It gets smaller as the ribs move in","correct_answer":"It gets bigger as the ribs move up and out"}'::jsonb, 'The child thinks of "squeezing" the air in, not of making space for it.', 'Ask what the chest does when breathing in and offer "it gets smaller".', 'Put both hands on the ribs and take a deep breath: feel them move out and up.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.LIVING.THE_HUMAN_BREATHING_SYST.BREATHING_MOVEMENT.M_BI_AIR_PUSHES_CHEST', 'SCIE.G5.LIVING.THE_HUMAN_BREATHING_SYST.BREATHING_MOVEMENT', 'Thinks the air fills the chest and pushes the ribs out, so the air does the work.', '{"question":"What is the first thing that happens when you breathe in?","wrong_answer":"Air rushes in and pushes the chest out","correct_answer":"The diaphragm and rib muscles move and the chest gets bigger"}'::jsonb, 'The child reverses cause and effect: air arrives first, the chest follows.', 'Ask what comes first and offer "air comes in".', 'Use a bell-jar model: pulling the rubber sheet down makes the balloon fill. The air follows the space.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.LIVING.THE_HUMAN_BREATHING_SYST.BREATHING_ILLNESS_SYMPTOMS.M_BS_ASTHMA_CATCHING', 'SCIE.G5.LIVING.THE_HUMAN_BREATHING_SYST.BREATHING_ILLNESS_SYMPTOMS', 'Thinks asthma can be caught from another person.', '{"question":"Can a child catch asthma from a classmate who has it?","wrong_answer":"Yes, it spreads like a cold","correct_answer":"No, asthma does not spread from person to person"}'::jsonb, 'The child treats every illness of the chest or throat as catching.', 'Ask whether asthma spreads and offer "yes".', 'Compare asthma (airways narrow, not an infection) with a cold (a virus that spreads).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.LIVING.THE_HUMAN_BREATHING_SYST.BREATHING_ILLNESS_SYMPTOMS.M_BS_ALLERGY_IS_INFECTION', 'SCIE.G5.LIVING.THE_HUMAN_BREATHING_SYST.BREATHING_ILLNESS_SYMPTOMS', 'Thinks sneezing and itchy eyes from dust or pollen are a cold caught from someone.', '{"question":"Wambui sneezes and has itchy eyes every time she sweeps the dusty classroom. What is the most likely cause?","wrong_answer":"She has caught a cold from another child","correct_answer":"She has an allergy to the dust"}'::jsonb, 'The child links sneezing with colds only.', 'Give the sneezing story with dust and offer "caught a cold".', 'Ask when the sneezing starts and stops: if it begins with dust and ends when the dust is gone, it points to an allergy.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.LIVING.THE_HUMAN_BREATHING_SYST.BREATHING_ILLNESS_SYMPTOMS.M_BS_ALL_SAME', 'SCIE.G5.LIVING.THE_HUMAN_BREATHING_SYST.BREATHING_ILLNESS_SYMPTOMS', 'Thinks all coughs and colds are the same illness with the same cause.', '{"question":"Which of these can spread from one person to another?","wrong_answer":"Asthma","correct_answer":"A common cold"}'::jsonb, 'The child treats every breathing problem as "a cough".', 'Ask which can spread and put asthma or allergy next to the cold.', 'List causes: cold and COVID-19 by viruses, asthma and allergy by sensitive airways.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.LIVING.THE_HUMAN_BREATHING_SYST.BREATHING_ILLNESS_PREVENTION.M_BV_COLD_WEATHER', 'SCIE.G5.LIVING.THE_HUMAN_BREATHING_SYST.BREATHING_ILLNESS_PREVENTION', 'Thinks a cold is caused by cold weather, rain or a cold drink.', '{"question":"What causes a common cold?","wrong_answer":"Cold weather and getting wet in the rain","correct_answer":"A virus that spreads from one person to another"}'::jsonb, 'Colds are more common in the cold season and the child links the two as cause and effect.', 'Ask for the cause of a cold and offer cold weather.', 'Show how the cold spreads when someone coughs without covering. Weather can help the virus spread but does not cause it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.LIVING.THE_HUMAN_BREATHING_SYST.BREATHING_ILLNESS_PREVENTION.M_BV_ANTIBIOTICS', 'SCIE.G5.LIVING.THE_HUMAN_BREATHING_SYST.BREATHING_ILLNESS_PREVENTION', 'Thinks medicine called antibiotics cures a cold or COVID-19.', '{"question":"Juma has a cold. What helps him get better?","wrong_answer":"Taking antibiotics, which kill the cold virus","correct_answer":"Rest and drinking water; antibiotics do not kill viruses"}'::jsonb, 'The child has heard that clinics give medicine for coughs and thinks one medicine fits all illnesses.', 'Ask what cures a cold and offer antibiotics.', 'Separate viruses (colds, COVID-19) from bacteria (some chest infections). Only a health worker decides on medicine.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.LIVING.THE_HUMAN_BREATHING_SYST.BREATHING_ILLNESS_PREVENTION.M_BV_HANDS_NO_MATTER', 'SCIE.G5.LIVING.THE_HUMAN_BREATHING_SYST.BREATHING_ILLNESS_PREVENTION', 'Thinks washing hands does not matter for illnesses of the breathing system.', '{"question":"Why does washing hands help to stop a cold spreading?","wrong_answer":"It does not help, because colds are only in the nose","correct_answer":"Germs on the hands can reach the nose and mouth"}'::jsonb, 'The child connects handwashing with stomach illnesses only.', 'Ask why wash hands to stop a cold and offer "it does not help".', 'Show glitter on the hands to see how it reaches the face.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.LIVING.THE_HUMAN_BREATHING_SYST.BREATHING_ILLNESS_PREVENTION.M_BV_SMOKE_HARMLESS', 'SCIE.G5.LIVING.THE_HUMAN_BREATHING_SYST.BREATHING_ILLNESS_PREVENTION', 'Thinks smoke from a cooking fire in a closed room is harmless.', '{"question":"Why is it better to cook outdoors or in a kitchen with a chimney?","wrong_answer":"Smoke does not harm the lungs, so it makes no difference","correct_answer":"Smoke can harm the lungs and make coughing and asthma worse"}'::jsonb, 'Smoke from cooking is part of everyday life and the child has never linked it to illness.', 'Ask about smoke in the kitchen and offer "no difference".', 'Ask the class how their eyes and chest feel in a smoky kitchen.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.LIVING.THE_HUMAN_BREATHING_SYST.BREATHING_PARTS.M_BP_NOSE_MOUTH_ONLY', 'SCIE.G5.LIVING.THE_HUMAN_BREATHING_SYST.BREATHING_PARTS', 'Thinks breathing happens only in the nose and mouth, with nothing going further inside.', '{"question":"Where does the air go after you breathe it in through your nose?","wrong_answer":"It stays in the nose","correct_answer":"Down the windpipe into the lungs"}'::jsonb, 'Feels air only at the nose and cannot see further.', 'Offer "It stays in the nose" next to the right answer and ask the question again in a new context.', 'Breathe in deeply with a hand on the chest: the chest rises because air goes into the lungs.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.LIVING.THE_HUMAN_BREATHING_SYST.BREATHING_MOVEMENT.M_BI_DIAPHRAGM_UP_IN', 'SCIE.G5.LIVING.THE_HUMAN_BREATHING_SYST.BREATHING_MOVEMENT', 'Thinks the diaphragm moves up when we breathe in.', '{"question":"When you breathe in, does the diaphragm move up or down?","wrong_answer":"Up","correct_answer":"Down: it flattens and makes more room in the chest"}'::jsonb, 'Sees the chest rise and thinks everything moves up.', 'Offer "Up" next to the right answer and ask the question again in a new context.', 'Pull the rubber sheet of the bottle model down: the balloons fill.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.LIVING.THE_HUMAN_BREATHING_SYST.BREATHING_MOVEMENT.M_BI_BREATHE_OUT_EMPTY', 'SCIE.G5.LIVING.THE_HUMAN_BREATHING_SYST.BREATHING_MOVEMENT', 'Thinks breathing out empties the lungs completely.', '{"question":"After you breathe out as hard as you can, are your lungs empty?","wrong_answer":"Yes, all the air is gone","correct_answer":"No: some air always stays in the lungs"}'::jsonb, 'Pictures the lungs as balloons that go flat.', 'Offer "Yes, all the air is gone" next to the right answer and ask the question again in a new context.', 'Breathe out hard, then still blow a little more on a strip of paper: air remains.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.LIVING.THE_HUMAN_BREATHING_SYST.BREATHING_ILLNESS_SYMPTOMS.M_BS_LONG_COUGH_IGNORED', 'SCIE.G5.LIVING.THE_HUMAN_BREATHING_SYST.BREATHING_ILLNESS_SYMPTOMS', 'Thinks a cough that lasts for weeks is just a normal cold that needs no check.', '{"question":"A person has coughed for three weeks and is losing weight. What should they do?","wrong_answer":"Nothing, it is just a cold","correct_answer":"Go to a health centre to be checked (it may be TB)"}'::jsonb, 'Has had many short colds and thinks all coughs are the same.', 'Offer "Nothing, it is just a cold" next to the right answer and ask the question again in a new context.', 'Talk through the signs that need a health worker: a cough over two weeks, blood, weight loss.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.MATTER.MIXTURES.MIXTURE_MEANING.M_MM_CANNOT_BE_UNMIXED', 'SCIE.G5.MATTER.MIXTURES.MIXTURE_MEANING', 'Thinks that once substances are mixed they change into something new and cannot be got back.', '{"question":"Salt is stirred into water and seems to disappear. Can the salt be got back?","wrong_answer":"No, the salt has gone for ever","correct_answer":"Yes, the salt is still there and can be got back"}'::jsonb, 'The child confuses mixing with cooking or burning, where new substances do form.', 'Use dissolving or sand and water and ask whether the parts are still there.', 'Leave salty water in the sun in a plate. The salt reappears as the water dries.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.MATTER.MIXTURES.MIXTURE_MEANING.M_MM_NATURAL_NOT_MIXTURE', 'SCIE.G5.MATTER.MIXTURES.MIXTURE_MEANING', 'Thinks a mixture must be made on purpose, so air, soil and muddy water are single things.', '{"question":"Is air a mixture?","wrong_answer":"No, air is one substance","correct_answer":"Yes, it is made of several gases"}'::jsonb, 'The child links the word mixture with kitchen or classroom mixing.', 'Ask about air or soil and offer "one substance".', 'Look at soil in water: sand, clay and bits of plants settle in layers.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.MATTER.MIXTURES.MIXTURE_MEANING.M_MM_EQUAL_PARTS', 'SCIE.G5.MATTER.MIXTURES.MIXTURE_MEANING', 'Thinks the parts of a mixture must be in equal amounts.', '{"question":"Wafula puts one spoon of sand in a bucket of water. Is it a mixture?","wrong_answer":"No, the parts are not equal","correct_answer":"Yes, the parts can be in any amounts"}'::jsonb, 'The child mixes up mixtures with recipes that need fixed amounts.', 'Use very different amounts and offer "not a mixture".', 'Make three sand-and-water mixtures of different amounts and compare.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.MATTER.MIXTURES.HOMOGENEOUS_OR_HETEROGENEOUS.M_MH_DISSOLVED_GONE', 'SCIE.G5.MATTER.MIXTURES.HOMOGENEOUS_OR_HETEROGENEOUS', 'Thinks dissolved salt or sugar has disappeared, so salty water is only water, not a mixture.', '{"question":"Is salt dissolved in water a mixture?","wrong_answer":"No, the salt has disappeared so it is only water","correct_answer":"Yes, it is a homogeneous mixture of salt and water"}'::jsonb, 'The child cannot see the salt, so thinks it is gone.', 'Use a clear salt solution and offer "only water".', 'Taste the water, or let it dry to show the salt.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.MATTER.MIXTURES.HOMOGENEOUS_OR_HETEROGENEOUS.M_MH_CLEAR_IS_PURE', 'SCIE.G5.MATTER.MIXTURES.HOMOGENEOUS_OR_HETEROGENEOUS', 'Thinks a clear liquid must be pure, one substance only.', '{"question":"Sugar is dissolved in clear water. Is the water pure?","wrong_answer":"Yes, because it is clear","correct_answer":"No, it is a mixture of sugar and water"}'::jsonb, 'Clear and clean are used as the same word.', 'Offer "yes, it is clear" as a reason.', 'Taste the sugar water: clear but sweet.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.MATTER.MIXTURES.HOMOGENEOUS_OR_HETEROGENEOUS.M_MH_STIRRED_IS_HOMO', 'SCIE.G5.MATTER.MIXTURES.HOMOGENEOUS_OR_HETEROGENEOUS', 'Thinks stirring makes any mixture the same all through (soil in water, oil in water).', '{"question":"Muddy water is stirred well. Is it homogeneous?","wrong_answer":"Yes, because it has been stirred it looks the same all through","correct_answer":"No, the soil settles and different parts can be seen"}'::jsonb, 'The child sees an even brown for a short time and calls it uniform.', 'Use a freshly stirred sand or soil mixture.', 'Stir soil in water and leave it for ten minutes. Layers form.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.MATTER.MIXTURES.MIXTURE_TYPES.M_MT_LOOKS_LIQUID', 'SCIE.G5.MATTER.MIXTURES.MIXTURE_TYPES', 'Calls salt dissolved in water a liquid-liquid mixture because it looks like liquid.', '{"question":"Salt is dissolved in water. What type of mixture is this?","wrong_answer":"Liquid-liquid","correct_answer":"Solid-liquid"}'::jsonb, 'The child classifies by how the mixture looks after mixing, not by the states of the parts before.', 'Use dissolving examples and offer liquid-liquid.', 'Name the state of each part before they were mixed: salt (solid), water (liquid).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.MATTER.MIXTURES.MIXTURE_TYPES.M_MT_THICK_IS_SOLID', 'SCIE.G5.MATTER.MIXTURES.MIXTURE_TYPES', 'Thinks a thick liquid (cooking oil, honey) is a solid.', '{"question":"Cooking oil is mixed with water. What type of mixture is this?","wrong_answer":"Solid-liquid, because oil is thick","correct_answer":"Liquid-liquid"}'::jsonb, 'The child equates thick with solid.', 'Use oil, honey or milk and offer solid-liquid.', 'Pour oil: it flows and takes the shape of its container, so it is a liquid.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.MATTER.MIXTURES.SEPARATION_METHOD_CHOICE.M_MS_FILTER_FOR_ALL', 'SCIE.G5.MATTER.MIXTURES.SEPARATION_METHOD_CHOICE', 'Thinks filtering separates any mixture, including dissolved salt or stones from rice.', '{"question":"Which method separates stones from rice?","wrong_answer":"Filtering","correct_answer":"Picking"}'::jsonb, 'Filtering is the best-known method and the child uses it for everything.', 'Offer filtering for a dry solid-solid mixture.', 'Filter paper only works when one part is a liquid with solid bits in it. Try salt water on filter paper and taste the water.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.MATTER.MIXTURES.SEPARATION_METHOD_CHOICE.M_MS_MAGNET_ANY_METAL', 'SCIE.G5.MATTER.MIXTURES.SEPARATION_METHOD_CHOICE', 'Thinks a magnet picks up every metal (aluminium, copper, brass).', '{"question":"A jua kali worker has iron nails and aluminium bits mixed in a box. What can a magnet pick out?","wrong_answer":"Both the nails and the aluminium bits","correct_answer":"Only the iron nails"}'::jsonb, 'The child has learned "magnets pick up metals" and has not tested different metals.', 'Mix an iron item with aluminium or copper and ask what the magnet takes.', 'Test an iron nail, an aluminium sufuria piece and a copper wire with a magnet.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.MATTER.MIXTURES.SEPARATION_METHOD_CHOICE.M_MS_FUNNEL_SOLIDS', 'SCIE.G5.MATTER.MIXTURES.SEPARATION_METHOD_CHOICE', 'Thinks a separating funnel separates a solid from a liquid.', '{"question":"Which mixture is separated with a separating funnel?","wrong_answer":"Sand and water","correct_answer":"Cooking oil and water"}'::jsonb, 'The child knows the funnel is for liquids and does not know it needs two liquids that do not mix.', 'Offer sand and water for a funnel.', 'Pour oil and water in a funnel and open the tap: the water comes first. Try sand and water and see that it is not suited.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.MATTER.MIXTURES.SEPARATION_PRINCIPLE.M_MP_FILTER_REMOVES_DISSOLVED', 'SCIE.G5.MATTER.MIXTURES.SEPARATION_PRINCIPLE', 'Thinks filtering removes dissolved salt or sugar from water.', '{"question":"Salty water is poured through filter paper. What is in the water that comes through?","wrong_answer":"Only water, the filter keeps the salt back","correct_answer":"Water and the dissolved salt"}'::jsonb, 'The child thinks the paper catches everything that is not water.', 'Ask what drips through filter paper after salt solution and offer "only water".', 'Filter salty water and taste it. It is still salty. Boil it down to see the salt.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.MATTER.MIXTURES.SEPARATION_PRINCIPLE.M_MP_WINNOW_REVERSED', 'SCIE.G5.MATTER.MIXTURES.SEPARATION_PRINCIPLE', 'Thinks that in winnowing the wind blows the heavy grain away and the light chaff stays.', '{"question":"When grain is winnowed, what does the wind blow away?","wrong_answer":"The heavier grain","correct_answer":"The lighter chaff"}'::jsonb, 'The child has seen the activity but not tied the result to weight.', 'Ask what the wind blows away and offer the grain.', 'Drop a coin and a feather in front of a fan to see which one is blown away.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.MATTER.MIXTURES.SEPARATION_PRINCIPLE.M_MP_SIEVE_REVERSED', 'SCIE.G5.MATTER.MIXTURES.SEPARATION_PRINCIPLE', 'Thinks the small pieces stay on the sieve and the big ones fall through.', '{"question":"Maize flour with husks is passed through a sieve. What stays on the sieve?","wrong_answer":"The fine flour","correct_answer":"The big husks"}'::jsonb, 'The child thinks of the sieve as a net that catches little things.', 'Ask what stays in the sieve and offer the fine flour.', 'Sieve sand and small stones and look at what remains.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.MATTER.MIXTURES.SEPARATION_USES.M_MU_ONLY_LAB', 'SCIE.G5.MATTER.MIXTURES.SEPARATION_USES', 'Thinks separating mixtures is only done in a science laboratory.', '{"question":"Where do people separate mixtures?","wrong_answer":"Only in a science laboratory","correct_answer":"At home, in the shamba and at work as well as in a laboratory"}'::jsonb, 'The child connects science words with the lab.', 'Ask where mixtures are separated and offer "only in a laboratory".', 'List the actions a family does in a day: sieve flour, pick stones from beans, strain tea.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.MATTER.MIXTURES.SEPARATION_USES.M_MU_FILTER_IS_SAFE', 'SCIE.G5.MATTER.MIXTURES.SEPARATION_USES', 'Thinks filtering muddy water makes it safe to drink.', '{"question":"Muddy water is filtered through a clean cloth. Is the water now safe to drink?","wrong_answer":"Yes, because it looks clean","correct_answer":"No, germs and dissolved things can still be in it"}'::jsonb, 'The child thinks that clear means safe.', 'Ask whether filtered water is safe and offer "yes".', 'Remember: germs are too small to be caught by a cloth. The water must also be boiled or treated.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.MATTER.MIXTURES.MIXTURE_MEANING.M_MM_DISSOLVED_IS_NEW', 'SCIE.G5.MATTER.MIXTURES.MIXTURE_MEANING', 'Thinks sugar dissolved in tea has turned into a new substance (sweet tea), not a mixture.', '{"question":"Sugar is stirred into tea. What has happened?","wrong_answer":"The sugar has become a new substance","correct_answer":"The sugar is mixed in; the tea and sugar are still there"}'::jsonb, 'Cannot see the sugar, so thinks it has changed.', 'Offer "The sugar has become a new substance" next to the right answer and ask the question again in a new context.', 'Leave a saucer of sugary tea to dry: sugar crystals are left.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.MATTER.MIXTURES.HOMOGENEOUS_OR_HETEROGENEOUS.M_MH_TWO_LIQUIDS_ALWAYS_HOMO', 'SCIE.G5.MATTER.MIXTURES.HOMOGENEOUS_OR_HETEROGENEOUS', 'Thinks any two liquids poured together give a homogeneous mixture, so oil and water are the same all through.', '{"question":"Cooking oil and water are poured into a glass. What kind of mixture is it?","wrong_answer":"Homogeneous, both are liquids","correct_answer":"Heterogeneous: the oil forms a layer on top"}'::jsonb, 'Expects liquids to blend because both pour.', 'Offer "Homogeneous, both are liquids" next to the right answer and ask the question again in a new context.', 'Pour oil onto water in a clear bottle and leave it: two layers form.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.MATTER.MIXTURES.MIXTURE_TYPES.M_MT_GAS_NOT_PART', 'SCIE.G5.MATTER.MIXTURES.MIXTURE_TYPES', 'Leaves out gases: thinks a mixture can only be made of solids and liquids, so air or soda is not a mixture.', '{"question":"Is soda with its bubbles a mixture?","wrong_answer":"No, a mixture is only solids and liquids","correct_answer":"Yes: it is a liquid with gas (carbon dioxide) mixed in"}'::jsonb, 'Has only met mixtures of solids and liquids.', 'Offer "No, a mixture is only solids and liquids" next to the right answer and ask the question again in a new context.', 'Open a bottle of soda: the bubbles are a gas leaving the liquid.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.MATTER.MIXTURES.MIXTURE_TYPES.M_MT_NAME_BY_LOOK', 'SCIE.G5.MATTER.MIXTURES.MIXTURE_TYPES', 'Names a mixture by how it looks at the end (muddy water is "a liquid") instead of by its parts.', '{"question":"What type of mixture is muddy water?","wrong_answer":"A liquid","correct_answer":"Solid-liquid (soil and water)"}'::jsonb, 'Answers with the state of the whole instead of its parts.', 'Offer "A liquid" next to the right answer and ask the question again in a new context.', 'Leave muddy water to settle: the soil (solid) and the water (liquid) show.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.MATTER.MIXTURES.SEPARATION_METHOD_CHOICE.M_MS_EVAPORATE_SAND', 'SCIE.G5.MATTER.MIXTURES.SEPARATION_METHOD_CHOICE', 'Chooses evaporation to get sand out of water, when filtering or decanting is quicker and keeps the water.', '{"question":"What is the best way to separate sand from water when you want to keep the water?","wrong_answer":"Boil the water away","correct_answer":"Filter it (or let it settle and pour off the water)"}'::jsonb, 'Knows evaporation separates things but not when it wastes a part.', 'Offer "Boil the water away" next to the right answer and ask the question again in a new context.', 'Ask which part is wanted: if it is the water, do not boil it away.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.MATTER.MIXTURES.SEPARATION_PRINCIPLE.M_MP_MAGNET_PULLS_SAND', 'SCIE.G5.MATTER.MIXTURES.SEPARATION_PRINCIPLE', 'Thinks a magnet separates iron filings from sand because it pulls the sand away.', '{"question":"Why does a magnet separate iron filings from sand?","wrong_answer":"It pushes the sand away","correct_answer":"Iron is attracted by a magnet and sand is not"}'::jsonb, 'Mixes up which part is attracted.', 'Offer "It pushes the sand away" next to the right answer and ask the question again in a new context.', 'Run a magnet over each part alone: only the iron filings jump to it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.MATTER.MIXTURES.SEPARATION_USES.M_MU_ONLY_ONE_METHOD_FARM', 'SCIE.G5.MATTER.MIXTURES.SEPARATION_USES', 'Thinks farmers use only one method (picking) and do not sieve, winnow or decant at home.', '{"question":"How does a farmer separate chaff from threshed beans in a windy place?","wrong_answer":"Pick out each bean by hand only","correct_answer":"Winnow: toss them in the wind so the light chaff blows away"}'::jsonb, 'Has only seen picking done.', 'Offer "Pick out each bean by hand only" next to the right answer and ask the question again in a new context.', 'Winnow a tray of beans and chaff outside on a windy day.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.MATTER.MIXTURES.SEPARATION_USES.M_MU_TEA_STRAINER_FILTER', 'SCIE.G5.MATTER.MIXTURES.SEPARATION_USES', 'Does not see a tea strainer or a cloth for straining as separating a mixture.', '{"question":"When you pour tea through a strainer, what are you doing?","wrong_answer":"Nothing special, just pouring","correct_answer":"Separating tea leaves from the liquid (filtering)"}'::jsonb, 'Thinks "separating mixtures" is a lab activity with special words.', 'Offer "Nothing special, just pouring" next to the right answer and ask the question again in a new context.', 'Hold up a strainer and ask what stays on it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.MATTER.WATER_POLLUTION.POLLUTANT_IDENTIFY.M_WP_ONLY_VISIBLE', 'SCIE.G5.MATTER.WATER_POLLUTION.POLLUTANT_IDENTIFY', 'Thinks water is polluted only if dirt can be seen, so clear water is clean.', '{"question":"The water in a stream looks clear. Does that mean it is not polluted?","wrong_answer":"Yes, clear water cannot be polluted","correct_answer":"No, germs and chemicals cannot be seen"}'::jsonb, 'The child uses looks as the test for clean water.', 'Offer "clear water is clean" as an answer.', 'Dissolve soap or salt in a glass of water: it is clear but not clean to drink.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.MATTER.WATER_POLLUTION.POLLUTANT_IDENTIFY.M_WP_ONLY_FACTORIES', 'SCIE.G5.MATTER.WATER_POLLUTION.POLLUTANT_IDENTIFY', 'Thinks only factories pollute water.', '{"question":"Which of these can pollute a river?","wrong_answer":"Only a factory pipe","correct_answer":"A factory pipe, washing at the river and a latrine near the bank"}'::jsonb, 'The child links pollution with big machines and smoke.', 'Offer "only factories" and list home sources.', 'Make a map of the school stream and list every source of waste along it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.MATTER.WATER_POLLUTION.POLLUTANT_IDENTIFY.M_WP_HELPFUL_THINGS_SAFE', 'SCIE.G5.MATTER.WATER_POLLUTION.POLLUTANT_IDENTIFY', 'Thinks useful things such as soap and fertiliser cannot pollute water.', '{"question":"Fertiliser helps maize grow. Can it pollute a river?","wrong_answer":"No, it helps plants so it cannot harm water","correct_answer":"Yes, rain can wash it into the river and it harms living things there"}'::jsonb, 'The child links useful with harmless.', 'Use fertiliser, soap or pesticide and offer "cannot pollute".', 'Look at a pond green with algae after too much fertiliser washed into it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.MATTER.WATER_POLLUTION.POLLUTION_EFFECTS.M_WE_ONLY_PEOPLE', 'SCIE.G5.MATTER.WATER_POLLUTION.POLLUTION_EFFECTS', 'Thinks polluted water harms only people, not animals and plants.', '{"question":"Oil spills into a river. What happens to the fish?","wrong_answer":"Nothing, pollution only harms people","correct_answer":"Many fish may die or fall ill"}'::jsonb, 'The child thinks of dirty water as a danger to drinkers.', 'Ask about fish or crops and offer "nothing".', 'Look at pictures of an oil spill near a shore.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.MATTER.WATER_POLLUTION.POLLUTION_EFFECTS.M_WE_UPSTREAM_ONLY', 'SCIE.G5.MATTER.WATER_POLLUTION.POLLUTION_EFFECTS', 'Thinks pollution harms only the place where it was dumped, not people downstream.', '{"question":"A factory dumps waste into a river. Who may be harmed?","wrong_answer":"Only people next to the factory","correct_answer":"People and animals living further down the river"}'::jsonb, 'The child pictures pollution as staying put.', 'Ask who is harmed and offer "only the place where it was dumped".', 'Put food colouring in a gutter model and watch it travel.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.MATTER.WATER_POLLUTION.POLLUTION_EFFECTS.M_WE_BAD_TASTE_ONLY', 'SCIE.G5.MATTER.WATER_POLLUTION.POLLUTION_EFFECTS', 'Thinks polluted water is only a problem if it smells or tastes bad.', '{"question":"Water from a stream has no smell and no bad taste. Is it safe to drink?","wrong_answer":"Yes, it has no smell or taste","correct_answer":"Not necessarily, it can have germs that cause diarrhoea"}'::jsonb, 'The child uses smell and taste as the test.', 'Offer "smells fine, so safe".', 'Remember that cholera germs have no smell.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.MATTER.WATER_POLLUTION.POLLUTION_PREVENTION.M_WR_RIVER_WASHES_AWAY', 'SCIE.G5.MATTER.WATER_POLLUTION.POLLUTION_PREVENTION', 'Thinks a big river washes waste away, so a little rubbish does not matter.', '{"question":"Kamau says \"The river is big, so one bag of rubbish does no harm.\" What is wrong with this?","wrong_answer":"Nothing, a big river washes it away","correct_answer":"The waste does not disappear; it spreads and harms people and animals downstream"}'::jsonb, 'The child thinks that carrying away is the same as making harmless.', 'Offer "the river is big" as an answer.', 'Show a bucket of coloured water poured into a larger bucket: the colour only spreads.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.MATTER.WATER_POLLUTION.POLLUTION_PREVENTION.M_WR_LATRINE_NEAR_WELL', 'SCIE.G5.MATTER.WATER_POLLUTION.POLLUTION_PREVENTION', 'Thinks a latrine close to a well or river is fine.', '{"question":"Where is the best place to dig a latrine?","wrong_answer":"Next to the well, so it is easy to reach","correct_answer":"Far from the well and the river"}'::jsonb, 'The child thinks of convenience, not of how water moves through the soil.', 'Offer a place close to the water.', 'Pour coloured water through soil near a model well.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.MATTER.WATER_POLLUTION.POLLUTION_PREVENTION.M_WR_WASH_IN_RIVER', 'SCIE.G5.MATTER.WATER_POLLUTION.POLLUTION_PREVENTION', 'Thinks washing clothes or cars in the river is harmless.', '{"question":"Where should a family wash clothes to keep a stream clean?","wrong_answer":"In the stream, because the soap washes away","correct_answer":"Away from the stream, pouring the used water on the ground"}'::jsonb, 'The child sees the river as the easiest place for the job.', 'Offer washing in the stream.', 'Ask what is in used wash water: soap, oil and dirt.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.MATTER.WATER_POLLUTION.WATER_TREATMENT_CHOICE.M_WT_FILTER_MAKES_SAFE', 'SCIE.G5.MATTER.WATER_POLLUTION.WATER_TREATMENT_CHOICE', 'Thinks filtering water makes it safe to drink.', '{"question":"A family filters stream water through cloth. What must they still do before drinking it?","wrong_answer":"Nothing, filtering makes it safe","correct_answer":"Boil it or treat it to kill germs"}'::jsonb, 'The child thinks that clear means safe and that filters kill germs.', 'Ask what to do after filtering and offer "nothing".', 'Compare the water under a microscope picture: germs are far smaller than the holes in cloth.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.MATTER.WATER_POLLUTION.WATER_TREATMENT_CHOICE.M_WT_BOIL_REMOVES_ALL', 'SCIE.G5.MATTER.WATER_POLLUTION.WATER_TREATMENT_CHOICE', 'Thinks boiling removes dirt and chemicals from water.', '{"question":"Water polluted with soap and oil is boiled. Is it now safe to drink?","wrong_answer":"Yes, boiling removes everything harmful","correct_answer":"No, boiling kills germs but does not remove soap or oil"}'::jsonb, 'The child sees boiling as the cure for all water problems.', 'Offer boiling for a chemical problem.', 'Boil salty water: it is still salty.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.MATTER.WATER_POLLUTION.WATER_TREATMENT_CHOICE.M_WT_SOLAR_MUDDY', 'SCIE.G5.MATTER.WATER_POLLUTION.WATER_TREATMENT_CHOICE', 'Thinks muddy water can be treated in the sun in a bucket without filtering.', '{"question":"Which water is suitable for solar treatment in a clear plastic bottle?","wrong_answer":"Muddy water straight from the river","correct_answer":"Water that has been left to settle and filtered until it is clear"}'::jsonb, 'The child does not know that mud blocks the sun''s rays and shields germs.', 'Offer muddy water for solar treatment.', 'Place two bottles in the sun: one clear and one muddy.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.MATTER.WATER_POLLUTION.WATER_TREATMENT_CHOICE.M_WT_MORE_CHLORINE', 'SCIE.G5.MATTER.WATER_POLLUTION.WATER_TREATMENT_CHOICE', 'Thinks more chlorine makes the water safer.', '{"question":"A mother adds three times the amount of water treatment tablet shown on the packet. What is the problem?","wrong_answer":"None, more chlorine makes it safer","correct_answer":"Too much chlorine makes the water taste bad and can harm people; the packet amount should be used"}'::jsonb, 'The child believes more of a cleaning thing is always better.', 'Offer "more is safer".', 'Read the packet instructions together.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.MATTER.WATER_POLLUTION.POLLUTANT_IDENTIFY.M_WP_NATURAL_NEVER_POLLUTES', 'SCIE.G5.MATTER.WATER_POLLUTION.POLLUTANT_IDENTIFY', 'Thinks natural things such as animal dung or soil washed in by rain cannot pollute water.', '{"question":"Cattle drink and leave dung in a stream. Is the water polluted?","wrong_answer":"No, dung is natural","correct_answer":"Yes: dung carries germs that make people ill"}'::jsonb, 'Thinks "pollution" means only factory or plastic waste.', 'Offer "No, dung is natural" next to the right answer and ask the question again in a new context.', 'Ask what is in dung (germs) and who drinks downstream.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.MATTER.WATER_POLLUTION.POLLUTION_EFFECTS.M_WE_ILLNESS_INSTANT', 'SCIE.G5.MATTER.WATER_POLLUTION.POLLUTION_EFFECTS', 'Thinks polluted water makes you ill straight away, so if nobody fell ill at once the water was safe.', '{"question":"A family drank river water and nobody was ill that day. Was the water safe?","wrong_answer":"Yes, nobody was ill","correct_answer":"Not necessarily: illnesses like typhoid show days later"}'::jsonb, 'Expects cause and effect to be immediate.', 'Offer "Yes, nobody was ill" next to the right answer and ask the question again in a new context.', 'Tell how cholera and typhoid start some days after drinking dirty water.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.MATTER.WATER_POLLUTION.POLLUTION_PREVENTION.M_WR_BURY_CHEMICALS_SAFE', 'SCIE.G5.MATTER.WATER_POLLUTION.POLLUTION_PREVENTION', 'Thinks pouring leftover pesticide on the ground near a river is safe because the soil will hold it.', '{"question":"A farmer has pesticide left over. Is pouring it on the ground near the river safe?","wrong_answer":"Yes, the soil soaks it up","correct_answer":"No: rain washes it into the river; follow the label for disposal"}'::jsonb, 'Thinks soil swallows things for good.', 'Offer "Yes, the soil soaks it up" next to the right answer and ask the question again in a new context.', 'Pour coloured water on a slope of soil and spray it: the colour runs downhill.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.FORCE_.FLOATING_AND_SINKING.FLOAT_OR_SINK.M_FA_HEAVY_SINKS', 'SCIE.G5.FORCE_.FLOATING_AND_SINKING.FLOAT_OR_SINK', 'Thinks heavy things sink and light things float.', '{"question":"A big wooden log is much heavier than a small stone. Which one sinks?","wrong_answer":"The log, because it is heavier","correct_answer":"The stone, even though it is lighter"}'::jsonb, 'The child uses weight alone, the quality that is easy to feel in the hand.', 'Pair a heavy floater (log) with a light sinker (small stone or nail).', 'Drop a big log and a small stone in water. Repeat with a coin and a leaf.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.FORCE_.FLOATING_AND_SINKING.FLOAT_OR_SINK.M_FA_MATERIAL_ALWAYS', 'SCIE.G5.FORCE_.FLOATING_AND_SINKING.FLOAT_OR_SINK', 'Thinks a material always floats or always sinks: all metal sinks, all wood floats.', '{"question":"A steel ship is made of metal. Does it float or sink?","wrong_answer":"It sinks, because all metal sinks","correct_answer":"It floats"}'::jsonb, 'The child has learned a rule from a few objects and applies it to every object of that material.', 'Use a metal that floats (a tin bowl, a ship) or a wood that sinks (ebony).', 'Float a tin lid on its flat side, then push it under so it fills with water.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.FORCE_.FLOATING_AND_SINKING.FLOAT_OR_SINK.M_FA_DEEP_WATER', 'SCIE.G5.FORCE_.FLOATING_AND_SINKING.FLOAT_OR_SINK', 'Thinks an object that sinks in a basin would float in a lake because there is more water.', '{"question":"A stone sinks in a bucket of water. What happens if it is dropped in a deep lake?","wrong_answer":"It floats, because the lake is deeper","correct_answer":"It sinks, the same as in the bucket"}'::jsonb, 'The child thinks that more water holds things up more.', 'Offer "floats in deep water".', 'Drop the stone in a shallow dish and in a bucket. The result is the same.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.FORCE_.FLOATING_AND_SINKING.FLOAT_FACTORS.M_FF_SHAPE_NO_EFFECT', 'SCIE.G5.FORCE_.FLOATING_AND_SINKING.FLOAT_FACTORS', 'Thinks shape makes no difference: a ball of clay sinks, so a bowl of the same clay sinks too.', '{"question":"A ball of clay sinks. The same clay is made into a bowl shape. What happens?","wrong_answer":"It still sinks, because it is the same clay","correct_answer":"It can float, because the bowl shape pushes aside more water"}'::jsonb, 'The child thinks of the material and mass only.', 'Use a same-material pair with two shapes and offer "no change".', 'Float a foil boat and then crumple the same foil into a ball.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.FORCE_.FLOATING_AND_SINKING.FLOAT_FACTORS.M_FF_WEIGHT_ONLY', 'SCIE.G5.FORCE_.FLOATING_AND_SINKING.FLOAT_FACTORS', 'Thinks only weight decides, so a heavier object always sinks.', '{"question":"Two blocks have the same size. Block A is heavier than block B. Which is more likely to sink?","wrong_answer":"Both float the same way","correct_answer":"Block A, which is heavier for its size"}'::jsonb, 'The child ignores size when it is the same, or ignores weight when it is not.', 'Use a same-size pair and offer "same result".', 'Compare two cups of the same size filled with sand and with cotton.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.FORCE_.FLOATING_AND_SINKING.FLOAT_FACTORS.M_FF_SIZE_ONLY', 'SCIE.G5.FORCE_.FLOATING_AND_SINKING.FLOAT_FACTORS', 'Thinks bigger pieces of the same material sink and smaller ones float (or the other way round).', '{"question":"A small piece of dry wood floats. Will a much bigger piece of the same wood float?","wrong_answer":"No, it is too big","correct_answer":"Yes, it floats too"}'::jsonb, 'The child uses size alone.', 'Compare big and small pieces of one material.', 'Float a splinter and a log of the same wood.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.FORCE_.FLOATING_AND_SINKING.FLOAT_FACTORS.M_FF_LOAD_NO_EFFECT', 'SCIE.G5.FORCE_.FLOATING_AND_SINKING.FLOAT_FACTORS', 'Thinks adding a load to a floating object makes no difference.', '{"question":"More and more people climb into a small canoe on Lake Victoria. What happens?","wrong_answer":"Nothing changes, it floats just as high","correct_answer":"It floats lower and lower and can sink"}'::jsonb, 'The child has no idea of the push of water having a limit.', 'Use a canoe or a boat with passengers.', 'Add stones one by one to a floating plastic tub and watch it sink lower.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.FORCE_.FLOATING_AND_SINKING.FLOAT_APPLICATIONS.M_FU_STEEL_LIGHT', 'SCIE.G5.FORCE_.FLOATING_AND_SINKING.FLOAT_APPLICATIONS', 'Thinks a steel ship floats because steel is lighter than water.', '{"question":"Why does a huge steel ship float?","wrong_answer":"Because steel is lighter than water","correct_answer":"Because its shape pushes aside a lot of water"}'::jsonb, 'The child thinks floating means the material is light.', 'Ask why the ship floats and offer "steel is light".', 'A steel nail sinks. Shape the same steel into a bowl and it floats.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.FORCE_.FLOATING_AND_SINKING.FLOAT_APPLICATIONS.M_FU_FLOAT_NO_WEIGHT', 'SCIE.G5.FORCE_.FLOATING_AND_SINKING.FLOAT_APPLICATIONS', 'Thinks floating things weigh nothing.', '{"question":"A floating log is lifted out of the water onto a scale. What does the scale show?","wrong_answer":"Nothing, because floating things have no weight","correct_answer":"Its weight, as the log is heavy"}'::jsonb, 'The child thinks "not sinking" means "not heavy".', 'Ask about the weight of a floating thing.', 'Weigh a block of wood that floats.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.FORCE_.FLOATING_AND_SINKING.FLOAT_OR_SINK.M_FA_HALF_SUNK_SINKS', 'SCIE.G5.FORCE_.FLOATING_AND_SINKING.FLOAT_OR_SINK', 'Thinks an object that floats low in the water, mostly under the surface, is sinking.', '{"question":"A piece of wood floats with most of it under the water. Is it floating or sinking?","wrong_answer":"Sinking, most of it is under water","correct_answer":"Floating: it stays at the surface and does not go to the bottom"}'::jsonb, 'Expects a floater to sit on top of the water.', 'Offer "Sinking, most of it is under water" next to the right answer and ask the question again in a new context.', 'Watch ice in a glass: most of it is under the water, but it stays up.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.FORCE_.FLOATING_AND_SINKING.FLOAT_APPLICATIONS.M_FU_LIFE_JACKET_HEAVY', 'SCIE.G5.FORCE_.FLOATING_AND_SINKING.FLOAT_APPLICATIONS', 'Thinks a life jacket works by being heavy enough to hold a person still.', '{"question":"How does a life jacket help a person in a lake?","wrong_answer":"It is heavy and holds them still","correct_answer":"It is full of air or light material that floats, holding the person up"}'::jsonb, 'Does not link floating materials with being held up.', 'Offer "It is heavy and holds them still" next to the right answer and ask the question again in a new context.', 'Put an empty plastic bottle in a basin and push it down: feel it push back up.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.FORCE_.FLOATING_AND_SINKING.FLOAT_APPLICATIONS.M_FU_FISHERMEN_NO_FLOATS', 'SCIE.G5.FORCE_.FLOATING_AND_SINKING.FLOAT_APPLICATIONS', 'Does not see floats on fishing nets as an everyday use of floating.', '{"question":"Why do fishermen on Lake Victoria tie light floats to the top of their nets?","wrong_answer":"To make the net heavier","correct_answer":"So the top of the net floats and the net hangs open in the water"}'::jsonb, 'Has not linked floating with tools people use.', 'Offer "To make the net heavier" next to the right answer and ask the question again in a new context.', 'Show a net with floats at the top and weights at the bottom.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.FORCE_.SOUND_ENERGY.SOUND_SOURCES.M_SS_NO_VIBRATION', 'SCIE.G5.FORCE_.SOUND_ENERGY.SOUND_SOURCES', 'Thinks sound is made without anything moving, or that the sound is "in" the object.', '{"question":"What happens to the skin of a drum when it makes a sound?","wrong_answer":"It stays still; the sound is inside the drum","correct_answer":"It vibrates, moving quickly to and fro"}'::jsonb, 'The child cannot see the vibration and thinks nothing moves.', 'Ask what the drum skin does and offer "stays still".', 'Put rice grains on a drum and hit it: they jump. Hold a ruler off the edge of a desk and twang it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.FORCE_.SOUND_ENERGY.SOUND_SOURCES.M_SS_AIR_SILENT', 'SCIE.G5.FORCE_.SOUND_ENERGY.SOUND_SOURCES', 'Thinks that in a flute or whistle the air is not part of the sound, only the instrument.', '{"question":"What vibrates to make the sound in a flute?","wrong_answer":"The metal or wood of the flute only","correct_answer":"The air inside the flute"}'::jsonb, 'The child sees the instrument as the object that moves.', 'Ask what vibrates in a flute and offer the flute itself.', 'Blow across the top of a bottle and change the water level.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.FORCE_.SOUND_ENERGY.SOUND_SOURCES.M_SS_HIT_ONLY', 'SCIE.G5.FORCE_.SOUND_ENERGY.SOUND_SOURCES', 'Thinks sound is only made by hitting or banging things.', '{"question":"Which action can make a sound from a string?","wrong_answer":"Only hitting it with a stick","correct_answer":"Plucking it with a finger"}'::jsonb, 'The child has met drums and bells mostly.', 'Offer hitting as the only way.', 'Pluck a stretched rubber band, then blow across a bottle: sound without banging.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.FORCE_.SOUND_ENERGY.SOUND_TRAVEL.M_ST_ONLY_AIR', 'SCIE.G5.FORCE_.SOUND_ENERGY.SOUND_TRAVEL', 'Thinks sound travels only through air, not through water or solids.', '{"question":"A learner puts an ear to a wooden desk while a friend taps the other end. What happens?","wrong_answer":"She hears nothing, because sound only travels through air","correct_answer":"She hears the tap clearly, because sound travels through the wood"}'::jsonb, 'The child associates sound with the air they live in.', 'Use a solid or water and offer "only air".', 'Tap a desk and listen with the ear on it. Swimmers hear sounds under water.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.FORCE_.SOUND_ENERGY.SOUND_TRAVEL.M_ST_IN_SPACE', 'SCIE.G5.FORCE_.SOUND_ENERGY.SOUND_TRAVEL', 'Thinks sound travels through space.', '{"question":"An astronaut outside a spacecraft shouts. Can another astronaut far away hear it?","wrong_answer":"Yes, sound travels everywhere","correct_answer":"No, there is no air or other material in space to carry the sound"}'::jsonb, 'Films show explosions in space with sound.', 'Ask whether space can carry sound and offer "yes".', 'Ring a bell in a jar with the air pumped out (video). It goes quiet.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.FORCE_.SOUND_ENERGY.SOUND_TRAVEL.M_ST_FASTER_IN_AIR', 'SCIE.G5.FORCE_.SOUND_ENERGY.SOUND_TRAVEL', 'Thinks sound travels faster through air than through solids or water.', '{"question":"Through which material does sound travel fastest?","wrong_answer":"Air","correct_answer":"Steel"}'::jsonb, 'The child thinks that lighter materials let things travel faster.', 'Offer air as the fastest.', 'Listen to a train through a rail and through the air.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.FORCE_.SOUND_ENERGY.SOUND_TRAVEL.M_ST_LOUD_FASTER', 'SCIE.G5.FORCE_.SOUND_ENERGY.SOUND_TRAVEL', 'Thinks a louder sound travels faster than a quiet one.', '{"question":"Two drums are played, one very loud and one very quiet, at the same distance. Which sound arrives first?","wrong_answer":"The louder one","correct_answer":"They arrive at the same time"}'::jsonb, 'The child links loud with strong and strong with quick.', 'Offer "the louder one".', 'Watch a band at a distance: loud and quiet notes of the same beat arrive together.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.FORCE_.SOUND_ENERGY.SOUND_EFFECTS.M_SL_ONLY_EARS', 'SCIE.G5.FORCE_.SOUND_ENERGY.SOUND_EFFECTS', 'Thinks loud sound affects only the ears, and only for a short time.', '{"question":"Which problems can very loud noise cause?","wrong_answer":"It only makes the ears ring for a moment","correct_answer":"Damage to hearing, headaches and poor sleep"}'::jsonb, 'The child has felt ringing ears after a loud noise and thinks that is all.', 'Ask what loud noise can cause and offer the short ringing.', 'Ask the class how they feel after a long day in a very noisy place.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.FORCE_.SOUND_ENERGY.SOUND_EFFECTS.M_SL_GETS_USED', 'SCIE.G5.FORCE_.SOUND_ENERGY.SOUND_EFFECTS', 'Thinks that being used to a loud noise means it no longer harms.', '{"question":"A boda boda rider has driven near loud engines for years and says he is now used to the noise. What is true?","wrong_answer":"Because he is used to it, the noise cannot harm his hearing","correct_answer":"His hearing can still be getting damaged even if the noise no longer bothers him"}'::jsonb, 'The child thinks that feeling no discomfort means no harm.', 'Offer "used to it, so no harm".', 'Explain that the tiny hair cells in the ear are not renewed once damaged.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.FORCE_.SOUND_ENERGY.SOUND_EFFECTS.M_SL_MUSIC_SAFE', 'SCIE.G5.FORCE_.SOUND_ENERGY.SOUND_EFFECTS', 'Thinks loud music cannot harm hearing because it is pleasant.', '{"question":"A matatu plays music at full volume every day. What is true for the passengers?","wrong_answer":"It cannot harm them, because music is pleasant","correct_answer":"It can harm their hearing, because any very loud sound can"}'::jsonb, 'The child thinks that "noise" means only unpleasant sounds.', 'Offer "music cannot harm".', 'Ask what happens to the ears at a very loud concert.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.FORCE_.SOUND_ENERGY.SOUND_SOURCES.M_SS_STOP_VIBRATION_SOUND_GOES_ON', 'SCIE.G5.FORCE_.SOUND_ENERGY.SOUND_SOURCES', 'Thinks a drum keeps sounding after its skin is held still.', '{"question":"A drummer hits a drum and then holds the skin still with her hand. What happens to the sound?","wrong_answer":"It goes on the same","correct_answer":"It stops, because the skin stops vibrating"}'::jsonb, 'Does not link the sound with the vibration.', 'Offer "It goes on the same" next to the right answer and ask the question again in a new context.', 'Hit a drum and touch the skin lightly, then hold it firmly: the sound stops.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.FORCE_.SOUND_ENERGY.SOUND_EFFECTS.M_SL_LOUD_ONLY_ANNOYING', 'SCIE.G5.FORCE_.SOUND_ENERGY.SOUND_EFFECTS', 'Thinks loud sound is only annoying and cannot harm health or learning.', '{"question":"A school is next to a loud posho mill all day. Can the noise harm the learners?","wrong_answer":"No, it is only annoying","correct_answer":"Yes: it can damage hearing, cause headaches and make it hard to learn"}'::jsonb, 'Has felt noise as a bother, not as harm.', 'Offer "No, it is only annoying" next to the right answer and ask the question again in a new context.', 'List what happens to a person after a loud disco or a day by a loud machine.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.FORCE_.HEAT_TRANSFER.HEAT_MODES.M_HM_HEAT_RISES', 'SCIE.G5.FORCE_.HEAT_TRANSFER.HEAT_MODES', 'Thinks heat itself rises, so heat can only go upwards.', '{"question":"A hot metal rod is held sideways. In which direction does the heat spread?","wrong_answer":"Only upwards, because heat rises","correct_answer":"Along the rod, away from the hot end, in every direction"}'::jsonb, 'The child has heard "heat rises" and turns it into a rule about all heat.', 'Use a sideways or downward situation and offer "up only".', 'Hold a lit candle under, beside and over your hand and feel the warmth in all of them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.FORCE_.HEAT_TRANSFER.HEAT_MODES.M_HM_COLD_TRAVELS', 'SCIE.G5.FORCE_.HEAT_TRANSFER.HEAT_MODES', 'Thinks cold flows from ice or a cold object into a warm one.', '{"question":"A cold drink is held in a warm hand. What is moving?","wrong_answer":"Cold moves from the drink into the hand","correct_answer":"Heat moves from the hand into the drink"}'::jsonb, 'The child feels the cold and thinks something cold is arriving.', 'Offer "cold flows into the hand".', 'Put a thermometer in the hand and then on the bottle.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.FORCE_.HEAT_TRANSFER.HEAT_MODES.M_HM_SUN_NEEDS_AIR', 'SCIE.G5.FORCE_.HEAT_TRANSFER.HEAT_MODES', 'Thinks the sun''s heat reaches us by conduction through air, or needs air to travel.', '{"question":"Space between the Sun and the Earth is empty. How does the Sun''s heat reach us?","wrong_answer":"By conduction through the air","correct_answer":"By radiation, which needs nothing to carry it"}'::jsonb, 'The child pictures heat as needing something to travel through, like sound.', 'Ask how the sun''s heat arrives and offer conduction.', 'Hold a hand near a lit lamp and feel the warmth without touching.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.FORCE_.HEAT_TRANSFER.HEAT_MODES.M_HM_CONVECTION_SOLID', 'SCIE.G5.FORCE_.HEAT_TRANSFER.HEAT_MODES', 'Thinks convection can happen in solids, such as along a metal spoon.', '{"question":"Which mode moves heat along a metal spoon placed in hot tea?","wrong_answer":"Convection","correct_answer":"Conduction"}'::jsonb, 'The child has memorised the names and cannot tell which fits which material.', 'Offer convection for a solid.', 'Convection needs a fluid that can move. A spoon cannot move its particles around.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.FORCE_.HEAT_TRANSFER.HEAT_CONDUCTORS.M_HC_METAL_COLDER', 'SCIE.G5.FORCE_.HEAT_TRANSFER.HEAT_CONDUCTORS', 'Thinks metal is colder than wood or plastic because it feels colder.', '{"question":"A metal spoon and a wooden spoon have been in the same room all night. Which one is colder?","wrong_answer":"The metal spoon, because it feels colder","correct_answer":"Neither, they are the same temperature"}'::jsonb, 'The child uses the feeling in the hand as the temperature.', 'Use two things left in the same room and offer "metal is colder".', 'Measure both with a thermometer: the reading is the same.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.FORCE_.HEAT_TRANSFER.HEAT_CONDUCTORS.M_HC_WOOL_MAKES_HEAT', 'SCIE.G5.FORCE_.HEAT_TRANSFER.HEAT_CONDUCTORS', 'Thinks wool and blankets make heat of their own.', '{"question":"A cold child is wrapped in a woollen blanket. Where does the warmth come from?","wrong_answer":"The blanket makes heat","correct_answer":"The child''s own body, kept in by the blanket"}'::jsonb, 'The child feels warmth and credits the thing wrapped around.', 'Put a thermometer in a blanket alone and offer "the blanket makes heat".', 'Wrap a thermometer in a blanket: the temperature does not rise. Wrap a warm bottle and watch it stay warm.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.FORCE_.HEAT_TRANSFER.HEAT_CONDUCTORS.M_HC_CONDUCTOR_KEEPS_HEAT', 'SCIE.G5.FORCE_.HEAT_TRANSFER.HEAT_CONDUCTORS', 'Thinks a good conductor of heat keeps heat in for a long time.', '{"question":"Which pot handle is better for a hot sufuria?","wrong_answer":"Metal, because metal holds heat in","correct_answer":"Wood, because it does not carry heat to the hand"}'::jsonb, 'The child mixes up carrying heat (conducting) with keeping heat in.', 'Ask which handle is safe and offer metal.', 'Put a metal and a wooden spoon in hot water and feel the handles after a minute.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.FORCE_.HEAT_TRANSFER.HEAT_USES.M_HU_COLOUR_NO_EFFECT', 'SCIE.G5.FORCE_.HEAT_TRANSFER.HEAT_USES', 'Thinks the colour of a surface makes no difference to how hot it gets in the sun.', '{"question":"Two iron sheet roofs, one painted white and one painted black, stand in the sun. Which gets hotter?","wrong_answer":"Both the same, colour makes no difference","correct_answer":"The black one, as dark surfaces take in more of the sun''s heat"}'::jsonb, 'The child has not compared surfaces in the sun.', 'Offer "the same".', 'Put a white and a black tin in the sun with thermometers.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.FORCE_.HEAT_TRANSFER.HEAT_USES.M_HU_VENT_LOW', 'SCIE.G5.FORCE_.HEAT_TRANSFER.HEAT_USES', 'Thinks air vents for a hot room or kitchen are best low on the wall, because heat goes down.', '{"question":"Why is a vent put near the roof of a hot kitchen?","wrong_answer":"Heat goes downwards, so the vent has to catch it","correct_answer":"Hot air and smoke rise, so they go out through the vent at the top"}'::jsonb, 'The child has not met convection in air.', 'Offer a vent near the floor as correct.', 'Hold a candle flame near the top and bottom of a doorway and see the smoke go.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.FORCE_.HEAT_TRANSFER.HEAT_USES.M_HU_COOKING_ONLY', 'SCIE.G5.FORCE_.HEAT_TRANSFER.HEAT_USES', 'Thinks heat transfer matters only when cooking.', '{"question":"Which of these uses heat transfer?","wrong_answer":"Only cooking uses it","correct_answer":"Cooking, drying clothes in the sun and a flask that keeps tea hot all use it"}'::jsonb, 'The child thinks of heat in the kitchen only.', 'Offer "only cooking".', 'List the places in a day where heat moves: sun on the roof, tea cooling, wearing a jumper.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.FORCE_.HEAT_TRANSFER.HEAT_SAFETY.M_HS_WET_CLOTH', 'SCIE.G5.FORCE_.HEAT_TRANSFER.HEAT_SAFETY', 'Thinks a wet cloth is the safest thing to hold a hot sufuria with.', '{"question":"Wanjiru needs to lift a hot sufuria. Which cloth is safest to use?","wrong_answer":"A wet cloth, because water cools it","correct_answer":"A dry, thick cloth"}'::jsonb, 'The child thinks water always cools things.', 'Offer a wet cloth.', 'A wet cloth conducts heat and steam burns. Compare a dry and a wet cloth on a warm tin.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.FORCE_.HEAT_TRANSFER.HEAT_SAFETY.M_HS_OFF_FIRE_COOL', 'SCIE.G5.FORCE_.HEAT_TRANSFER.HEAT_SAFETY', 'Thinks a pot that is no longer on the fire, or has no flame or steam, is safe to touch.', '{"question":"A sufuria has just been taken off the jiko. There is no flame or steam. Is it safe to touch?","wrong_answer":"Yes, there is no flame or steam so it is cool","correct_answer":"No, it can stay hot for a long time"}'::jsonb, 'The child uses flame or steam as the sign of heat.', 'Offer "no flame so cool".', 'Hold a hand near, not on, the pot and feel the heat.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.FORCE_.HEAT_TRANSFER.HEAT_SAFETY.M_HS_METAL_HANDLE_OK', 'SCIE.G5.FORCE_.HEAT_TRANSFER.HEAT_SAFETY', 'Thinks a metal handle on a hot pan is safe because metal is strong.', '{"question":"A sufuria has a metal handle. What is the danger when it is on the fire?","wrong_answer":"None, metal is strong and safe","correct_answer":"The handle gets hot because metal carries heat to it"}'::jsonb, 'The child mixes up strong with safe.', 'Offer "none".', 'Put a metal and a wooden spoon in hot water and feel both handles.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.FORCE_.HEAT_TRANSFER.HEAT_CONDUCTORS.M_HC_INSULATOR_STOPS_COLD_ONLY', 'SCIE.G5.FORCE_.HEAT_TRANSFER.HEAT_CONDUCTORS', 'Thinks a flask or a blanket only keeps cold things cold, or only hot things hot, not both.', '{"question":"Can a flask keep cold water cold?","wrong_answer":"No, a flask is only for hot tea","correct_answer":"Yes: it slows heat moving in or out, so cold stays cold too"}'::jsonb, 'Has only seen flasks used for hot tea.', 'Offer "No, a flask is only for hot tea" next to the right answer and ask the question again in a new context.', 'Put cold water in a flask and a cup; feel both after an hour.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.FORCE_.HEAT_TRANSFER.HEAT_USES.M_HU_BLACK_POT_SLOW', 'SCIE.G5.FORCE_.HEAT_TRANSFER.HEAT_USES', 'Thinks a shiny pot heats faster in the sun than a black one.', '{"question":"Which water heats faster in the sun: in a black tin or a shiny tin?","wrong_answer":"The shiny tin","correct_answer":"The black tin"}'::jsonb, 'Links shiny with hot because shiny metal looks bright.', 'Offer "The shiny tin" next to the right answer and ask the question again in a new context.', 'Put water in a black and a shiny tin in the sun and feel them after an hour.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SCIE.G5.FORCE_.HEAT_TRANSFER.HEAT_SAFETY.M_HS_HANDLE_TURNED_OUT', 'SCIE.G5.FORCE_.HEAT_TRANSFER.HEAT_SAFETY', 'Thinks a pan handle should point out over the edge of the stove so it is easy to grab.', '{"question":"How should the handle of a hot pan on a stove be turned?","wrong_answer":"Out over the edge, easy to reach","correct_answer":"Inwards, away from the edge, so nobody knocks it"}'::jsonb, 'Thinks only about easy reach.', 'Offer "Out over the edge, easy to reach" next to the right answer and ask the question again in a new context.', 'Act out a small child walking past a stove with a handle sticking out.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
